import os
roots = {
  'prod2': r'D:\repository\产品2.0\zhi2-web-admin',
  'v3': r'D:\repository\苏州市房地产监测V3\zhi2-web-admin',
  'szC': r'D:\repository\苏住房C\zhi2-mobile-shimin',
}
symbols = {
  'showReg': 'showRegulatoryAccountFields',
  'canEditReg': 'canEditRegulatoryAccountFields',
  'accountOpenType': 'accountOpenType',
  'loginAsCompany': 'loginAsCompany',
  'pwrCompUser': 'PLAYWRIGHT_COMPANY_USERNAME',
  'concat': 'company-record-change',
  'headroom': 'headroom',
  'compress_msg': 'compress(messages)',
  'isBTerm': 'isBTerminalPractitioner',
  'propertyProjectId': 'propertyProjectId',
  'queryForm': 'ref="queryForm"',
  'contentInfo': 'contentInfo',
  'top120': 'top-120',
  'pb260': 'pb-260',
  'flagSzf': 'flag-szf.svg',
}
path_tokens = ['pubRegulatoryAccount', os.path.join('rent','my','index.vue'),
               'guaranteeDepositAccount','ResultStatistics.vue','StepConfirm.vue',
               'companyRegister.vue','Step3Appendix.vue']
skip = {'dist','node_modules','.git','test-results','.dsh','coverage'}
exts = ('.vue','.js','.ts','.json','.jsx','.env','.scss','.css','.txt')
hits = {k: [] for k in symbols}
paths = {t: [] for t in path_tokens}
for rk, root in roots.items():
    if not os.path.isdir(root):
        print('MISSING_ROOT', rk, root); continue
    for dp, dn, fn in os.walk(root):
        dn[:] = [d for d in dn if d not in skip]
        for f in fn:
            if not f.endswith(exts): continue
            p = os.path.join(dp, f)
            rel = os.path.relpath(p, root)
            for t in path_tokens:
                if t.replace('/',os.sep) in rel:
                    if len(paths[t])<6: paths[t].append(rk+':'+rel)
            try:
                txt = open(p, encoding='utf-8', errors='ignore').read()
            except Exception:
                continue
            for k, s in symbols.items():
                if s in txt:
                    if len(hits[k])<6: hits[k].append(rk+':'+rel)
print('=== SYMBOLS ===')
for k in symbols: print(k, len(hits[k]), hits[k])
print('=== PATHS ===')
for t in path_tokens: print(t, len(paths[t]), paths[t])

